package com.apnishadi.config;
import com.apnishadi.connection.ConversationWebSocketHandler; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.Configuration; import org.springframework.web.socket.config.annotation.*;
@Configuration @EnableWebSocket public class WebSocketConfig implements WebSocketConfigurer { private final ConversationWebSocketHandler handler; private final JwtWebSocketHandshakeInterceptor auth; private final String[] origins; public WebSocketConfig(ConversationWebSocketHandler h,JwtWebSocketHandshakeInterceptor a,@Value("${app.cors.allowed-origins}") String o){handler=h;auth=a;origins=o.split(",");} @Override public void registerWebSocketHandlers(WebSocketHandlerRegistry r){r.addHandler(handler,"/ws/conversations/*").addInterceptors(auth).setAllowedOrigins(origins);} }
